-- 0135: My Hero Academia — drei Korrekturen (23.10.2026, beim Übersetzen gemeldet):
-- Dabi fehlt die Hitzeresistenz des VATERS (nicht die Kälteresistenz der Mutter),
-- das Sportfest ersetzte die Olympischen Spiele (nicht Prüfungen), All Might verlor
-- den ganzen Magen. correct_index bleibt. Idempotent (setzt feste Werte).
update question_translations set options = jsonb_set(options, '{0}', to_jsonb('Es ersetzt die Olympischen Spiele, Profihelden suchen dort Talente'::text)) where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Rolle spielt das Sportfest der U.A.?');
update question_translations set options = jsonb_set(options, '{0}', to_jsonb('It replaced the Olympics, and pro heroes scout talent there'::text)) where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Rolle spielt das Sportfest der U.A.?');
update question_translations set options = jsonb_set(options, '{0}', to_jsonb('Sustituyó a los Juegos Olímpicos y los héroes profesionales buscan talentos allí'::text)) where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Rolle spielt das Sportfest der U.A.?');
update question_translations set options = jsonb_set(options, '{0}', to_jsonb('Il a remplacé les Jeux olympiques, et les héros pros y repèrent des talents'::text)) where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Rolle spielt das Sportfest der U.A.?');
update question_translations set options = jsonb_set(options, '{0}', to_jsonb('Substituiu as Olimpíadas, e heróis profissionais procuram talentos lá'::text)) where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Rolle spielt das Sportfest der U.A.?');
update question_translations set explanation = 'Der Kampf lag Jahre zurück – All Might verlor dabei seinen Magen und die Hälfte seiner Atmungsorgane.' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wer fügte All Might seine schwere Verletzung zu?');
update question_translations set explanation = 'The fight happened years earlier – All Might lost his stomach and half of his respiratory system.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wer fügte All Might seine schwere Verletzung zu?');
update question_translations set explanation = 'La pelea fue años antes: All Might perdió el estómago y la mitad de su sistema respiratorio.' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wer fügte All Might seine schwere Verletzung zu?');
update question_translations set explanation = 'Le combat a eu lieu des années plus tôt – All Might y a perdu l’estomac et la moitié de son système respiratoire.' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wer fügte All Might seine schwere Verletzung zu?');
update question_translations set explanation = 'A luta aconteceu anos antes – All Might perdeu o estômago e metade do sistema respiratório.' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wer fügte All Might seine schwere Verletzung zu?');
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('Er erbte das Feuer, aber nicht die Hitzeresistenz seines Vaters'::text)) where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Warum verbrennt Dabi an seinen eigenen Flammen?');
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('He inherited the fire but not his father’s heat resistance'::text)) where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Warum verbrennt Dabi an seinen eigenen Flammen?');
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('Heredó el fuego, pero no la resistencia al calor de su padre'::text)) where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Warum verbrennt Dabi an seinen eigenen Flammen?');
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('Il a hérité du feu, mais pas de la résistance à la chaleur de son père'::text)) where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Warum verbrennt Dabi an seinen eigenen Flammen?');
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('Herdou o fogo, mas não a resistência ao calor do pai'::text)) where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Warum verbrennt Dabi an seinen eigenen Flammen?');
